def find_length(binary_string):
    n = len(binary_string)
    if n == 0:
        return 0

    max_diff = 0
    zeros_count = [0] * (n + 1)
    ones_count = [0] * (n + 1)

    for i in range(n):
        zeros_count[i + 1] = zeros_count[i]
        ones_count[i + 1] = ones_count[i]

        if binary_string[i] == '0':
            zeros_count[i + 1] += 1
        else:
            ones_count[i + 1] += 1

    for i in range(n + 1):
        for j in range(i + 1, n + 1):
            diff = abs(zeros_count[j] - ones_count[j])
            diff -= abs(zeros_count[i] - ones_count[i])
            max_diff = max(max_diff, diff)

    return max_diff

