def is_Sum_Of_Powers_Of_Two(n):
    # Check if the given number n is zero, as zero cannot be represented as the sum of non-zero powers of 2
    if n == 0:
        return False

    # Iterate through the possible powers of 2 until 2**31 which is the largest power of 2 within the limit of 32-bit signed integer
    for i in range(31):
        # If the current power of 2 (2**i) is less than or equal to n, then subtract it from n
