def get_total_number_of_sequences(m, n):
    """
    Calculate the number of possible sequences of length n where each element is a positive integer,
    greater than or equal to twice the previous element but less than or equal to m.
    """
    if n == 0:
        return 1
    if m == 1:
        return 0

    # Helper function to calculate the total number of valid sequences
    def calculate_sequences(m, n):
        dp = [0] * (n + 1)
        dp[0] = 1  # Base case: there's one way to form a sequence of length 0

        for j in range(1, n + 1):
            current = math.inf
            for k in range(1, m + 1):
                if k >= j * 2:
                    current = min(current, dp[j - 1] + 1)
                else:
                    break
            dp[j] = current
        return dp[n]

    return calculate_sequences(m, n)

